 const hamburger = document.getElementById("hamburger");
 const sidemenu = document.getElementById("sidemenu");
 const closeBtn = document.getElementById("closeBtn");
 const submenu = document.getElementById("submenu");
 const navLinks = document.querySelectorAll(".nav a[data-menu], .sidemenu-left a[data-menu]");
 const overlay = document.getElementById("overlay");
 const mainNav = document.getElementById("mainNav");

// Submenu Inhalte
const submenuContent = {
 1: `

 • Home

 • Technology

 • Client Experiences

 • Sustainability

 • Customer Focus Network

 • 
 Countries

 • Germany | Headquarter

 • Austria

 • Belgium

 • Finland

 • Netherlands

 • Norway

 • Sweden

 • Switzerland

 • United Kingdom

 `,
 2: `

 • News Posts

 • Press Information

 `,
 3: `

 • coeo Family

 • Job Vacancies

 `,
 4: `

 • Overview

 • Styleguide

 • Brand Essence

 • Brand Stuff

 • Wear the Brand

 • At a Glance

 `
};

 // Öffnen
 function openMenu(menuId = 1) {
 sidemenu.classList.add("open");
 overlay.classList.add("active");
 submenu.innerHTML = submenuContent[menuId];
 setActive(menuId);

 // Header Nav + Hamburger anpassen
 mainNav.classList.add("hidden");
 hamburger.classList.add("hidden");
 }

 // Schließen
 function closeMenu() {
 sidemenu.classList.remove("open");
 overlay.classList.remove("active");
 clearActive();

 // Header Nav + Hamburger zurück
 mainNav.classList.remove("hidden");
 hamburger.classList.remove("hidden");
 }

 // Aktive Farbe setzen
 function setActive(menuId) {
 document.querySelectorAll(".sidemenu-left a").forEach(a => {
 a.classList.remove("active");
 if (a.dataset.menu === menuId.toString()) {
 a.classList.add("active");
 }
 });
 }
 function clearActive() {
 document.querySelectorAll(".sidemenu-left a").forEach(a => a.classList.remove("active"));
 }

 // Klick Events
 hamburger.addEventListener("click", () => openMenu(1));
 closeBtn.addEventListener("click", closeMenu);
 overlay.addEventListener("click", closeMenu);
 navLinks.forEach(link => {
 link.addEventListener("click", (e) => {
 e.preventDefault();
 const menuId = e.target.dataset.menu;
 if(menuId) openMenu(menuId);
 });
 });

document.addEventListener("click", function (event) {
 const toggle = event.target.closest(".dropdown-toggle");
 if (!toggle) return;

 event.preventDefault();

 const parent = toggle.closest(".has-dropdown");
 parent.classList.toggle("open");
});

Azure Cloud Operations Engineer/Administrator (m/w/d)

Germany
Remote

full-time
Get to know coeo Germany

Deine Zukunft bei coeo:
• Als Azure Cloud Operations Engineer/Administrator (m/w/d) verantwortest Du den Aufbau, Betrieb und die Weiterentwicklung unserer Azure-Cloud- und Windows-Server-Landschaft
• Du übernimmst die Administration, Optimierung und Überwachung unserer Microsoft-Server inklusive Debugging und Tuning
• Du arbeitest mit Azure und hast Erfahrung in Bereichen wie Networking, Monitoring, Security und Microsoft 365
• Du automatisierst Day-2-Operations und setzt Infrastructure-as-Code ein
• Du unterstützt Kunden und interne Stakeholder bei technischen Fragestellungen und stellst einen stabilen Betrieb sicher
• Mit PowerShell, Python oder vergleichbaren Sprachen automatisierst und optimierst Du unsere Betriebsprozesse
• Bei Bedarf unterstützt Du im Rahmen von Bereitschaftsdiensten
• Du wirst Teil unseres wachsenden Teams, das Du aktiv mitgestalten kannst

Was Du mitbringst:
• Du hast eine abgeschlossene Ausbildung oder ein Studium im IT-Bereich, z. B. als Fachinformatiker (m/w/d) oder eine vergleichbare Qualifikation
• Du verfügst über mehrjährige Erfahrung in der Administration von Windows-Servern
• Du hast fundierte Kenntnisse im Microsoft-Umfeld sowie Erfahrung mit Microsoft 365 und Azure
• Kenntnisse der IKAROS-Software sind von Vorteil, aber kein Muss
• Deine ausgeprägten Problemlösungsfähigkeiten und Dein analytisches Denkvermögen zeichnen Dich aus
• Eigenverantwortung und Zuverlässigkeit sind für Dich selbstverständlich
• Du arbeitest gerne im Team, bist lernbereit und offen für neue Technologien und Weiterentwicklungen
• Sehr gute Deutsch- und Englischkenntnisse in Wort und Schrift

Deine Vorteile bei coeo:
• Team & Kultur: Freue Dich auf ein motiviertes Team, flache Hierarchien, kurze Entscheidungswege und eine offene, wertschätzende Unternehmenskultur
• Work-Life-Balance: 30 Urlaubstage, eine transparente Arbeitszeiterfassung und die Möglichkeit im Homeoffice zu arbeiten
• Sicherheit: Langfristige Perspektive mit einem unbefristeten Arbeitsvertrag
• Entwicklung: Vielfältige Weiterbildungs- und Entwicklungsmöglichkeiten, um Deine Karriere aktiv voranzubringen
• Gesundheit & Mobilität: JobRad Kooperation und kostenfreie Urban Sports Club Mitgliedschaft
• Attraktive Extras: Arbeitgeberzuschüsse, z. B. zur betrieblichen Altersvorsorge (bAV) oder zu vermögenswirksamen Leistungen (VWL), sowie exklusive Mitarbeiterrabatte über Corporate Benefits
• Verpflegung: Kostenfreie Getränke im Büro sowie vergünstigtes Mittagessen über unseren Kantinenservice
• Bequeme Anreise: Kostenfreie Parkplätze und eine gute Verkehrsanbindung an unseren Standorten

