 const nextBtn = document.getElementById('nextBtn');
 const step1 = document.getElementById('step1');
 const step2 = document.getElementById('step2');
 const wrapper = document.getElementById('personioFormWrapper');
 const thankyou = document.querySelector('.thankyou');

 nextBtn.addEventListener('click', () => {
 const firstName = document.querySelector('input[name="first_name"]').value.trim();
 const surname = document.querySelector('input[name="surname"]').value.trim();
 const email = document.querySelector('input[name="email"]').value.trim();
 const gdprStep1 = document.getElementById('gdpr_step1');
 const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

 if (!firstName || !surname || !email) {
 alert('Please fill all required fields marked with *');
 return;
 }
 if (!emailRegex.test(email)) {
 alert('Please enter a valid email address.');
 return;
 }
 if (!gdprStep1.checked) {
 alert('Please confirm that you have read the privacy information.');
 return;
 }

 step1.classList.remove('active');
 step2.classList.add('active');
 wrapper.scrollIntoView({ behavior: 'smooth' });
 });

 const drop = document.getElementById('fileDrop');
 const fileInput = document.getElementById('fileInput');
 const fileName = document.getElementById('fileName');
 const dropIcon = document.getElementById('dropIcon');

 drop.addEventListener('click', () => fileInput.click());

 document.getElementById('personioForm').addEventListener('submit', function(e) {
 e.preventDefault();

 if (!fileInput.files || fileInput.files.length === 0) {
 alert('Please upload your application documents before submitting.');
 return;
 }

 const sendBtn = document.getElementById('send-btn');
 sendBtn.disabled = true;
 sendBtn.textContent = 'Sending...';

 const formData = new FormData(this);

 fetch('https://www.coeo-group.ai/wp-admin/admin-ajax.php', {
 method: 'POST',
 body: formData,
 })
 .then(res => res.json())
 .then(data => {
 if (data.success) {
 this.style.display = 'none';
 thankyou.style.display = 'flex';
 wrapper.scrollIntoView({ behavior: 'smooth' });
 } else {
 alert(data.data || 'An error occurred. Please try again.');
 sendBtn.disabled = false;
 sendBtn.textContent = 'Submit';
 }
 })
 .catch(() => {
 alert('An error occurred. Please try again.');
 sendBtn.disabled = false;
 sendBtn.textContent = 'Submit';
 });
 });

 fileInput.addEventListener('change', () => {
 if(fileInput.files.length > 0){
 fileName.textContent = `Selected file: ${fileInput.files[0].name}`;
 drop.classList.add('file-selected');
 dropIcon.src = 'https://www.coeo-group.ai/wp-content/uploads/2025/12/check-thin-1.svg';

 // Text ausblenden
 document.getElementById('dropText').style.display = 'none';

 } else {
 fileName.textContent = '';
 drop.classList.remove('file-selected');
 dropIcon.src = 'https://www.coeo-group.ai/wp-content/uploads/2025/12/upload-simple-fill.svg';

 // Text wieder anzeigen
 document.getElementById('dropText').style.display = 'block';
 }
});

