/* =========================================================================
 BLOG SINGLE - SHARE LINKS

 Each share link is tagged in the Designer with data-share="linkedin" | "x"
 | "reddit" (Settings > Custom attributes), so the order of the icons can
 change without touching this script.

 The shared URL comes from the canonical link when present, so UTM and
 other query junk is never shared; it falls back to origin + pathname.
 The title prefers og:title, then the H1, then document.title - og:title
 is the clean headline, while document.title carries the " | Noma
 Security" suffix.

 Real hrefs are written onto the elements rather than hijacking the
 click, so middle-click, right-click and keyboard all keep working.
 ========================================================================= */
(function () {
 var BUILDERS = {
 linkedin: function (url) {
 return 'https://www.linkedin.com/sharing/share-offsite/?url=' + url;
 },
 x: function (url, title) {
 return 'https://x.com/intent/post?url=' + url + '&text=' + title;
 },
 reddit: function (url, title) {
 return 'https://www.reddit.com/submit?url=' + url + '&title=' + title;
 }
 };

 function shareUrl() {
 var c = document.querySelector('link[rel="canonical"]');
 if (c && c.href) return c.href;
 return window.location.origin + window.location.pathname;
 }

 function shareTitle() {
 var og = document.querySelector('meta[property="og:title"]');
 if (og && og.content && og.content.trim()) return og.content.trim();
 var h1 = document.querySelector('h1');
 if (h1 && h1.textContent && h1.textContent.trim()) return h1.textContent.trim();
 return document.title;
 }

 function init() {
 var url = encodeURIComponent(shareUrl());
 var title = encodeURIComponent(shareTitle());

 var links = document.querySelectorAll('[data-share]');
 Array.prototype.forEach.call(links, function (a) {
 var key = (a.getAttribute('data-share') || '').toLowerCase().trim();
 var build = BUILDERS[key];
 if (!build) return; /* unknown network - leave alone */
 a.setAttribute('href', build(url, title));
 a.setAttribute('target', '_blank');
 a.setAttribute('rel', 'noopener noreferrer');
 });
 }

 if (document.readyState === 'loading') {
 document.addEventListener('DOMContentLoaded', init);
 } else {
 init();
 }
})();

