function openApplyModal() {
 document.getElementById('applyModal').classList.remove('hidden');
 document.body.style.overflow = 'hidden';
}

 function closeApplyModal() {
 document.getElementById('applyModal').classList.add('hidden');
 document.body.style.overflow = 'auto';
 // Reset form and messages
 document.getElementById('applyForm').reset();
 hideMessages();
 }

 function showSuccessMessage() {
 document.getElementById('successMessage').classList.remove('hidden');
 document.getElementById('errorMessage').classList.add('hidden');
 // Hide form fields
 document.querySelectorAll('#applyForm > div:not(#successMessage):not(#errorMessage)').forEach(el => {
 el.style.display = 'none';
 });
 }

 function showErrorMessage(message) {
 document.getElementById('errorMessage').classList.remove('hidden');
 document.getElementById('successMessage').classList.add('hidden');
 document.getElementById('errorText').textContent = message;
 }

 function hideMessages() {
 document.getElementById('successMessage').classList.add('hidden');
 document.getElementById('errorMessage').classList.add('hidden');
 // Show form fields
 document.querySelectorAll('#applyForm > div:not(#successMessage):not(#errorMessage)').forEach(el => {
 el.style.display = '';
 });
 }

// Prevent duplicate submissions
let isSubmitting = false;

function submitForm() {
 // Prevent duplicate submissions
 if (isSubmitting) {
 // console.log('Form already submitting, ignoring duplicate request');
 return;
 }

 // Validate required fields
 const firstName = document.getElementById('firstName').value.trim();
 const lastName = document.getElementById('lastName').value.trim();
 const phone = document.getElementById('contactNumber').value.trim();
 const email = document.getElementById('emailAddress').value.trim();
 const cv = document.getElementById('cvUpload').files[0];

 if (!firstName || !lastName || !phone || !email || !cv) {
 showErrorMessage('Please fill in all required fields (First Name, Last Name, Contact Number, Email, and CV)');
 return;
 }

 isSubmitting = true;
 // console.log('Starting form submission');

 // Show loading state
 const submitBtn = document.getElementById('submitApplication');
 const submitText = document.getElementById('submitText');
 const loadingText = document.getElementById('loadingText');

 submitBtn.disabled = true;
 submitText.classList.add('hidden');
 loadingText.classList.remove('hidden');

 // Get form data
 const formData = new FormData(document.getElementById('applyForm'));

 // Add WordPress AJAX action
 formData.append('action', 'submit_job_application');

 // Send AJAX request
 fetch('https://www.scoreapp.com/wp/wp-admin/admin-ajax.php', {
 method: 'POST',
 body: formData
 })
 .then(response => response.json())
 .then(data => {
 // console.log('Form submission response:', data);
 if (data.success) {
 showSuccessMessage();
 // Auto-close modal after 3 seconds
 setTimeout(() => {
 closeApplyModal();
 }, 3000);
 } else {
 showErrorMessage('Error: ' + (data.data || 'Something went wrong. Please try again.'));
 }
 })
 .catch(error => {
 // console.error('Error:', error);
 showErrorMessage('Something went wrong. Please try again.');
 })
 .finally(() => {
 // Reset button state and submission flag
 submitBtn.disabled = false;
 submitText.classList.remove('hidden');
 loadingText.classList.add('hidden');
 isSubmitting = false;
 // console.log('Form submission completed');
 });
}

// Close modal when clicking outside
document.getElementById('applyModal').addEventListener('click', function(e) {
 if (e.target === this) {
 closeApplyModal();
 }
});

// Close modal with Escape key
document.addEventListener('keydown', function(e) {
 if (e.key === 'Escape') {
 closeApplyModal();
